import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to allow any withdrawal
        c.SetMinSum(0);
        // Set a dummy log file
        c.SetLogFile(address(0xdead));
        // Initialize the contract
        c.Initialized();

        // Prepare actors
        address alice = address(0x1111);
        address bob = address(0x2222);

        // Alice deposits 200 wei
        vm.deal(alice, 200);
        vm.prank(alice);
        c.Deposit{value: 200}();

        // Bob deposits 100 wei
        vm.deal(bob, 100);
        vm.prank(bob);
        c.Deposit{value: 100}();

        // Bob calls Collect(50)
        vm.prank(bob);
        c.Collect(50);

