        vm.deal(bob, 200);
        vm.prank(bob);
        c.Deposit{value: 100}();
        // Now Bob calls Collect(100) — Bob's balance is 100, MinSum is 0, so condition passes
        vm.prank(bob);
        c.Collect(100);
        // After Collect in the reference: balances[bob] = 100 - 100 = 0
        // After Collect in the buggy: balances[bob] = 100 + 100 = 200
        // Assert that Bob's balance is 0 (reference passes, buggy fails)
        assertTrue(c.balances(bob) == 0);
    }
}

contract LogFile
{
    struct Message
    {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;

    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

